SELECT satscores.rtype, schools.soc as school_code, schools.soctype as school_type, AVG(satscores.avgscrread) as avg_reading, AVG(satscores.avgscrmath) as avg_math, AVG(satscores.avgscrwrite) as avg_writing, COUNT(*) as school_count FROM satscores JOIN schools ON satscores.cds = schools.cdscode GROUP BY satscores.rtype, schools.soc, schools.soctype ORDER BY schools.soctype, schools.soc, satscores.rtype;
